const body = $json.body || $json;

// 1. Filtrar eventos (aceita messages.upsert, messages-upsert, MESSAGES_UPSERT ou se event nao vier informado)
const event = String(body.event || '').toLowerCase();
if (event && !event.includes('upsert')) {
  return []; // Ignora updates de entrega (delivered, read), presence, etc.
}

// 2. Tratar data como objeto ou array
let data = body.data || body;
if (Array.isArray(data)) {
  if (data.length === 0) return [];
  data = data[0];
}

const key = data.key || {};

// 3. Ignorar terminantemente se a mensagem foi enviada pelo proprio bot (fromMe)
if (key.fromMe === true || String(key.fromMe) === 'true' || data.fromMe === true) {
  return [];
}

// 4. Ignorar mensagens de grupos ou status do WhatsApp
const remoteJid = key.remoteJid || data.remoteJid || '';
if (!remoteJid || remoteJid.includes('@g.us') || remoteJid.includes('status@broadcast')) {
  return [];
}

// 5. Extrair texto real da mensagem em todos os formatos possiveis
const msg = data.message || {};
const text = 
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  msg.buttonsResponseMessage?.selectedDisplayText ||
  msg.listResponseMessage?.title ||
  msg.imageMessage?.caption ||
  msg.videoMessage?.caption ||
  data.body ||
  '';

// 6. Se nao houver texto digitado (status, aviso de leitura), nao processa
if (!text || !String(text).trim()) {
  return [];
}

// 7. Extrair dados limpos
const wa_id = remoteJid.replace(/@.*$/, '').replace(/\D/g, '');
const message_id = key.id || data.id || `evo_${Date.now()}`;
const timestamp = String(data.messageTimestamp || Math.floor(Date.now() / 1000));
const profile_name = data.pushName || wa_id;
const phone_number_id = (data.owner || "").replace(/\D/g, '') || "897759766750800";

return [{
  json: {
    event_classification: "inbound_customer_message",
    wa_id: wa_id,
    phone_number_id: phone_number_id,
    profile_name: profile_name,
    text: String(text).trim(),
    message_id: message_id,
    timestamp: timestamp,
    type: "text",
    data: {
      key: {
        fromMe: false
      }
    },
    meta_raw: body
  }
}];
